-- 0137_ims_hira_aspect.sql
--
-- THE HIRA AND THE ASPECT-IMPACT REGISTER, POPULATED (Dr Raghu, 5 Sep 2026):
-- "This is the HIRA - populate it and also add additional fields as needed"
-- and "this is the aspect impact register, we need to incorporate all this
-- too." Both come from the IMS Google Sheet (NGSE/R/SYS/04 and NGSE/R/SYS/05).
--
-- The two system registers get the sheet's real columns plus the ones an
-- auditor asks for next (legal reference, PPE, emergency response, life-cycle
-- stage, OCP reference, monitoring). Columns carrying `product` or `level_of`
-- are computed by the engine: inherent risk = impact x probability, the
-- aspect score = Q x I x O x C x D, and the risk level bands 1-4 Low, 5-9
-- Medium, 10-15 High, 16-25 Extreme.
--
-- Every row carries import_key so a re-run adds nothing twice and never
-- touches a row somebody has since edited. ASCII only, additive, safe to re-run.


update ims_register_definition set columns = $j$[{"key": "scope", "label": "Scope", "type": "select", "options": ["Plant (general)", "Hi Lift", "Scissor lift", "Office", "Site / customer premises"], "required": true}, {"key": "category", "label": "Hazard category", "type": "short"}, {"key": "sr_no", "label": "Sr no", "type": "number"}, {"key": "hazard", "label": "Hazard / risk", "type": "text", "required": true}, {"key": "persons_at_risk", "label": "Persons at risk", "type": "short"}, {"key": "significant_risk", "label": "Significant risk to health and safety", "type": "text"}, {"key": "impact_rating", "label": "Impact rating", "type": "select", "options": ["1 - Insignificant", "2 - Minor", "3 - Moderate", "4 - Very High", "5 - Extreme"]}, {"key": "probability_rating", "label": "Probability rating", "type": "select", "options": ["1 - Rare", "2 - Unlikely", "3 - Possible", "4 - Likely", "5 - Almost certain"]}, {"key": "inherent_risk", "label": "Inherent risk (I x P)", "type": "number", "product": ["impact_rating", "probability_rating"]}, {"key": "risk_level", "label": "Risk level", "type": "select", "options": ["Low", "Medium", "High", "Extreme"], "level_of": "inherent_risk"}, {"key": "mce", "label": "Present mitigation control effectiveness (MCE)", "type": "text"}, {"key": "control_measures", "label": "Control measures to be taken as action of plan", "type": "text"}, {"key": "responsibility", "label": "Responsibility", "type": "short"}, {"key": "impact_after", "label": "Impact rating after controls", "type": "select", "options": ["1 - Insignificant", "2 - Minor", "3 - Moderate", "4 - Very High", "5 - Extreme"]}, {"key": "probability_after", "label": "Probability rating after controls", "type": "select", "options": ["1 - Rare", "2 - Unlikely", "3 - Possible", "4 - Likely", "5 - Almost certain"]}, {"key": "residual_risk", "label": "Level of risk after control", "type": "number", "product": ["impact_after", "probability_after"]}, {"key": "residual_level", "label": "Residual risk level", "type": "select", "options": ["Low", "Medium", "High", "Extreme"], "level_of": "residual_risk"}, {"key": "action_plan", "label": "Action plan", "type": "text"}, {"key": "legal_ref", "label": "Legal / statutory reference", "type": "short"}, {"key": "ppe", "label": "PPE required", "type": "short"}, {"key": "emergency_response", "label": "Emergency response", "type": "short"}, {"key": "assessed_on", "label": "Assessed on", "type": "date"}, {"key": "assessed_by", "label": "Assessed by", "type": "short"}, {"key": "evidence", "label": "Evidence", "type": "file"}]$j$::jsonb, description = 'ISO 45001 clause 6.1.2 - Hazard / Risk Identification and Control (NGSE/R/SYS/04, QHE-F-02). The plant, the Hi Lift and the Scissor lift, each hazard with its inherent risk, the controls, and the risk left after them.' where slug = 'hira';

update ims_register_definition set columns = $j$[{"key": "assessment", "label": "Assessment", "type": "select", "options": ["Shop floor, office and administration (Rev 0, revised 02/12/2024)", "Original register (Rev 0, 15/07/2023)"], "required": true}, {"key": "area", "label": "Activity area", "type": "short"}, {"key": "sr_no", "label": "Sr no", "type": "number"}, {"key": "input", "label": "Input", "type": "short"}, {"key": "output", "label": "Activity / output", "type": "short"}, {"key": "aspect", "label": "Environmental aspect", "type": "text", "required": true}, {"key": "lifecycle", "label": "Life-cycle stage", "type": "select", "options": ["Procurement", "Use / operation", "Maintenance", "Disposal / end of life"]}, {"key": "condition", "label": "Condition", "type": "select", "options": ["Normal", "Abnormal", "Emergency", "Environmental"]}, {"key": "impact", "label": "Environmental impact", "type": "text"}, {"key": "impact_on", "label": "Impact on", "type": "short"}, {"key": "concern", "label": "Concern (LC / IPC / BC / SP)", "type": "short"}, {"key": "direct_indirect", "label": "Direct / indirect", "type": "select", "options": ["Direct", "Indirect"]}, {"key": "controls", "label": "Controls available", "type": "text"}, {"key": "quantity", "label": "Quantity (Q)", "type": "select", "options": ["1 - Insignificant", "2 - Low", "3 - Medium", "4 - High"]}, {"key": "impact_rating", "label": "Impact (I)", "type": "select", "options": ["1 - Temporary damage to property and employees", "2 - Reversible damage to property and employees", "3 - Irreversible damage to property and employees", "4 - Irreversible damage to many people and local environment"]}, {"key": "occurrence", "label": "Occurrence (O)", "type": "select", "options": ["1 - Rarely", "2 - Yearly", "3 - Monthly", "4 - Daily"]}, {"key": "control", "label": "Control (C)", "type": "select", "options": ["1 - Effective control exists", "2 - Control exists but not effective", "3 - No control"]}, {"key": "detectable", "label": "Detectable (D)", "type": "select", "options": ["1 - Detectable", "2 - Not detectable"]}, {"key": "score", "label": "Score (Q x I x O x C x D)", "type": "number", "product": ["quantity", "impact_rating", "occurrence", "control", "detectable"]}, {"key": "significance", "label": "Significance (SA / NSA)", "type": "select", "options": ["Significant", "Not significant"]}, {"key": "ocp_ref", "label": "OCP reference", "type": "short"}, {"key": "legal_ref", "label": "Legal requirement", "type": "short"}, {"key": "objective", "label": "Objective / target linked", "type": "short"}, {"key": "monitoring", "label": "Monitoring method", "type": "short"}, {"key": "remarks", "label": "Remarks", "type": "text"}]$j$::jsonb, description = 'ISO 14001 clause 6.1.2 - Aspect-Impact Register (NGSE/R/SYS/05). Every activity by area, its aspect and impact, the condition, and the Q x I x O x C x D score that decides significance.' where slug = 'aspect-impact';

insert into ims_register_entry (register_id, data, status, created_by)
select d.id, $j${"scope": "Plant (general)", "category": "Physical Hazards", "sr_no": 1, "hazard": "Slips, Trips, and Falls 1. Slippery floors 2. loose cables 3. uneven surfaces 4. cluttered walkways", "persons_at_risk": "Employees & Visitors", "significant_risk": "minor bruises and sprains to severe fractures", "impact_rating": "2 - Minor", "probability_rating": "2 - Unlikely", "inherent_risk": 4, "mce": "Effective", "control_measures": "Maintain good housekeeping practices", "responsibility": "Safety Officer & Supervisors", "impact_after": "1 - Insignificant", "probability_after": "2 - Unlikely", "residual_risk": 2, "risk_level": "Low", "residual_level": "Low", "assessed_on": "2024-12-02", "assessed_by": "PS", "import_key": "sheet:hira:1"}$j$::jsonb, 'open', 'import:ims-sheet'
from ims_register_definition d where d.slug = 'hira' and not exists (select 1 from ims_register_entry e where e.register_id = d.id and e.data->>'import_key' = 'sheet:hira:1');

